package com.yumi.cafe.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@Entity @Table(name="orders",indexes={@Index(name="idx_orders_created",columnList="createdAt"),@Index(name="idx_orders_status",columnList="status")})
public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String orderNumber; @Column(nullable=false) String customerName,phone,fulfillmentType; @Column(length=1000) String address; @Column(nullable=false) BigDecimal subtotal,deliveryFee,total; @Column(nullable=false) String paymentMethod; @Column(nullable=false) String paymentStatus; @Column(nullable=false) String status; @Column(nullable=false) Instant createdAt=Instant.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) List<OrderItem> items=new ArrayList<>();
 public Long getId(){return id;}public String getOrderNumber(){return orderNumber;}public void setOrderNumber(String v){orderNumber=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getFulfillmentType(){return fulfillmentType;}public void setFulfillmentType(String v){fulfillmentType=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public BigDecimal getSubtotal(){return subtotal;}public void setSubtotal(BigDecimal v){subtotal=v;}public BigDecimal getDeliveryFee(){return deliveryFee;}public void setDeliveryFee(BigDecimal v){deliveryFee=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String v){paymentMethod=v;}public String getPaymentStatus(){return paymentStatus;}public void setPaymentStatus(String v){paymentStatus=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}public List<OrderItem> getItems(){return items;} public void addItem(OrderItem i){items.add(i);i.setOrder(this);}}
